const item = $input.first();
const input = item.json.body ?? item.json;
const text = (v) => (typeof v === 'string' ? v.trim() : '');

// 1. Company and job: one field that holds either a link or the full text
const company_name = text(input.company_name);
const job_posting = text(input.job_posting);
let job_description = text(input.job_description);
let job_url = text(input.job_url);
if (job_posting) {
  if (/^https?:\/\/\S+$/i.test(job_posting)) job_url = job_posting;
  else job_description = job_posting;
}
if (!company_name) throw new Error('Missing required non-empty field: company_name');
if (!job_description && !job_url) throw new Error('Provide the job posting as text or as a link');

// 2. CV file: PDF goes to the PDF reader later; .md and .txt are read here
const cv = item.binary?.cv;
let has_cv = false;
let cvFileText = '';
if (cv) {
  const name = (cv.fileName ?? '').toLowerCase();
  const isPdf = cv.mimeType === 'application/pdf' || name.endsWith('.pdf');
  const isText = /\.(md|txt)$/.test(name) || /^text\//.test(cv.mimeType ?? '');
  if (isPdf) {
    has_cv = true;
  } else if (isText) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, 'cv');
    cvFileText = buffer.toString('utf8').trim();
  } else {
    throw new Error('The cv file must be a PDF, .md, or .txt file');
  }
}

// 3. Candidate text = text from .md/.txt file + pasted text
const candidate_context = [cvFileText, text(input.candidate_context)].filter(Boolean).join('\n\n');

// 4. Length limits protect API costs
const values = { company_name, job_description, job_url, candidate_context };
const max = { company_name: 200, job_description: 20000, job_url: 2048, candidate_context: 30000 };
for (const [field, value] of Object.entries(values)) {
  if (value.length > max[field]) throw new Error(`Field ${field} exceeds the ${max[field]}-character limit`);
}

// 5. GitHub: accept a username or a profile link, keep only the username
const githubInput = text(input.github_profile);
let github_username = '';
if (githubInput) {
  const match = githubInput.match(/^(?:https?:\/\/)?(?:www\.)?github\.com\/([A-Za-z0-9-]{1,39})\/?$/i)
    ?? githubInput.match(/^([A-Za-z0-9-]{1,39})$/);
  if (!match) throw new Error('github_profile must be a GitHub username or profile URL');
  github_username = match[1];
}

// 6. At least one source about the candidate
if (!has_cv && !candidate_context && !github_username) {
  throw new Error('Provide at least one candidate source: cv, candidate_context, or github_profile');
}

const output = {
  json: { company_name, job_description, job_url, candidate_context, github_username,
          has_cv, has_github: Boolean(github_username) }
};
if (has_cv) output.binary = item.binary;
return [output];

const validated = $('Validate Input').first();
const original = validated.json;
const input = $input.first().json;

// Turn HTML into plain text
const toText = (s) => String(s ?? '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/gi, "'")
  .replace(/\s+/g, ' ')
  .trim();

let job_description = String(original.job_description ?? '').trim();

if (!job_description && original.job_url) {
  const raw = typeof input === 'string' ? input : (input.data ?? input.body ?? '');
  const html = String(raw).slice(0, 500000);

  // 1. Structured job data that many job sites include for Google (JobPosting)
  const blocks = html.match(/<script[^>]*application\/ld\+json[^>]*>[\s\S]*?<\/script>/gi) || [];
  for (const block of blocks) {
    try {
      const data = JSON.parse(block.replace(/^<script[^>]*>/i, '').replace(/<\/script>$/i, ''));
      const list = Array.isArray(data) ? data : (data['@graph'] ?? [data]);
      const posting = list.find((x) => x && x['@type'] === 'JobPosting');
      if (posting) {
        job_description = `${posting.title ?? ''}\n${toText(posting.description)}`.trim();
        break;
      }
    } catch (e) { /* skip broken data */ }
  }

  // 2. Fallback: the page's short description
  if (job_description.length < 50) {
    const og = html.match(/<meta[^>]*property="og:description"[^>]*content="([^"]*)"/i);
    job_description = toText(og?.[1] ?? '');
  }

  // 3. Still nothing useful: stop with a clear message
  job_description = job_description.slice(0, 20000);
    if (job_description.length < 300) {
    throw new Error('The job advertisement could not be read. Please paste the job description instead.');
  }
}

if (!job_description) throw new Error('No usable job description was provided');
return [{ json: { ...original, job_description }, binary: validated.binary }];

const validated = $('Validate Input').first().json;
const itemsFrom = (name) => {
  try { return $(name).all(); } catch (error) { return []; }
};
const notes = [];

// 1. CV text from the PDF, if one was uploaded
let cvText = '';
if (validated.has_cv) {
  cvText = String(itemsFrom('Extract CV Text')[0]?.json?.text ?? '').trim();
  if (cvText.length < 50) {
    cvText = '';
    notes.push('The CV could not be read, so it was not used.');
  }
}

// 2. All candidate text together: PDF text + pasted text / .md file
const candidate_text = [cvText, validated.candidate_context].filter(Boolean).join('\n\n').slice(0, 30000);

// 3. GitHub repositories, without forks (copies of other people's projects)
const github_repositories = validated.has_github
  ? itemsFrom('GitHub Repositories')
      .map((item) => item.json)
      .filter((repo) => repo.name && repo.html_url && !repo.fork)
      .map((repo) => ({
        name: repo.name,
        description: repo.description ?? '',
        language: repo.language ?? '',
        topics: repo.topics ?? [],
        stars: repo.stargazers_count ?? 0,
        last_pushed: repo.pushed_at ?? '',
        url: repo.html_url
      }))
  : [];
if (validated.has_github && github_repositories.length === 0) {
  notes.push('No public GitHub repositories were available, so GitHub was not used.');
}

// 4. Stop if there is no evidence about the candidate at all
if (!candidate_text && github_repositories.length === 0) {
  throw new Error('No usable candidate evidence was found in the CV, candidate text, or GitHub profile');
}
return [{ json: { candidate_text, github_repositories, data_notes: notes } }];

// 1. Read the AI answer
const content = $input.first().json.choices?.[0]?.message?.content;
if (typeof content !== 'string' || !content.trim()) {
  throw new Error('The requirement extraction returned no content');
}
let data;
try {
  data = JSON.parse(content);
} catch (error) {
  throw new Error(`The requirement extraction returned invalid JSON: ${error.message}`);
}

// 2. Keep only requirements whose quote really appears in the job ad
const job = $('Prepare Job Input').first().json.job_description.toLowerCase().replace(/\s+/g, ' ');
const clean = (v) => String(v ?? '').trim();
const requirements = (Array.isArray(data.requirements) ? data.requirements : [])
  .map((r) => ({
    track: clean(r.track) || 'General',
    requirement: clean(r.requirement),
    priority: r.priority === 'Nice-to-have' ? 'Nice-to-have' : 'Must-have',
    source_text: clean(r.source_text)
  }))
  .filter((r) => r.requirement && r.source_text.length >= 8 && job.includes(r.source_text.toLowerCase().replace(/\s+/g, ' ')))
  .slice(0, 8);
if (requirements.length === 0) {
  throw new Error('No requirements could be traced to the job description');
}

return [{ json: {
  role_title: clean(data.role_title),
  focus_area: clean(data.focus_area),
  tracks: [...new Set(requirements.map((r) => r.track))],
  requirements
} }];

const content = $input.first().json.choices?.[0]?.message?.content;
if (typeof content !== 'string' || !content.trim()) {
  throw new Error('The model response did not contain report content');
}
let report;
try {
  report = JSON.parse(content);
} catch (error) {
  throw new Error(`The model returned invalid JSON: ${error.message}`);
}
const required = ['company_background', 'recent_news', 'role_requirements', 'experience_match', 'projects_to_highlight', 'skill_gaps', 'interview_questions'];
for (const field of required) {
  if (!(field in report)) throw new Error(`Report is missing required section: ${field}`);
}
for (const field of ['recent_news', 'experience_match', 'projects_to_highlight', 'skill_gaps', 'interview_questions']) {
  if (!Array.isArray(report[field])) throw new Error(`Report section ${field} must be an array`);
}
if (report.interview_questions.length !== 5 || report.interview_questions.some((q) => typeof q?.question !== 'string' || typeof q?.based_on !== 'string' || !q.based_on.trim())) {
  throw new Error('Report must contain exactly five interview questions, each with question and based_on');
}
if (typeof report.company_background !== 'object' || report.company_background === null || typeof report.company_background.summary !== 'string') {
  throw new Error('Report section company_background must contain a summary');
}

const normalizeUrl = (url) => String(url ?? '').trim().toLowerCase().replace(/#.*$/, '').replace(/\/+$/, '');
// Compare only letters and numbers, and rejoin words split across lines in PDF text
const normalizeText = (value) => String(value ?? '').toLowerCase().replace(/-\s*\n\s*/g, '').replace(/[^\p{L}\p{N}]+/gu, ' ').trim();

const extracted = $('Parse Requirements').first().json;
report.role_requirements = extracted.requirements.map(({ track, requirement, priority }) => ({ track, requirement, priority }));
const requirementTexts = new Set(extracted.requirements.map((r) => normalizeText(r.requirement)));

const research = $('Company Research').first().json;
const researchUrls = new Set((Array.isArray(research.results) ? research.results : []).map((r) => normalizeUrl(r.url)));
const newsResponse = $('Find Recent News').first().json;
const newsUrls = new Set((Array.isArray(newsResponse.articles) ? newsResponse.articles : []).map((a) => normalizeUrl(a.url)));
const evidence = $('Build Candidate Evidence').first().json;
const candidateText = normalizeText(evidence.candidate_text);
const repositoryUrls = new Set(evidence.github_repositories.map((repo) => normalizeUrl(repo.url)));
const data_notes = [...(evidence.data_notes ?? [])];
if (!Array.isArray(research.results)) data_notes.push('Company research was unavailable, so the company background is limited.');
if (!Array.isArray(newsResponse.articles)) data_notes.push('The news service was unavailable, so no news is included.');
const removed_claims = [];
const remove = (section, reason, value) => removed_claims.push({ section, reason, value: value ?? '' });

const background = report.company_background;
const backgroundUrls = Array.isArray(background.source_urls) ? background.source_urls : [];
background.source_urls = backgroundUrls.filter((url) => {
  const ok = researchUrls.has(normalizeUrl(url));
  if (!ok) remove('company_background', 'Source URL was not in the search results', url);
  return ok;
});
if (background.source_urls.length === 0) {
  background.summary = 'Public information about this company is limited.';
  background.why_it_matters = '';
}

report.recent_news = report.recent_news.filter((news) => {
  const ok = newsUrls.has(normalizeUrl(news?.url));
  if (!ok) remove('recent_news', 'News URL was not in the news results', news?.url);
  return ok;
}).slice(0, 3);

const repositoryNames = new Set(evidence.github_repositories.map((repo) => normalizeText(String(repo.url ?? '').split('/').filter(Boolean).pop())));
const hasEvidence = (claim) => {
  if (claim?.evidence_source === 'github') {
    const repoName = normalizeText(String(claim.evidence_url ?? '').split('/').filter(Boolean).pop());
    return repositoryUrls.has(normalizeUrl(claim.evidence_url)) || (repoName.length > 0 && repositoryNames.has(repoName));
  }
  if (claim?.evidence_source === 'candidate_text') {
    const quote = normalizeText(claim.evidence_quote || claim.evidence || claim.project);
    return quote.length >= 8 && candidateText.includes(quote);
  }
  return false;
};
const matchedRequirements = new Set();
report.experience_match = report.experience_match.filter((claim) => {
  if (!requirementTexts.has(normalizeText(claim?.requirement))) {
    remove('experience_match', 'Requirement was not one of the extracted requirements', claim?.requirement);
    return false;
  }
  if (!['Strong', 'Partial'].includes(claim?.strength)) {
    remove('experience_match', 'Strength must be Strong or Partial', claim?.requirement);
    return false;
  }
  if (typeof claim?.match_reason !== 'string' || !claim.match_reason.trim()) {
    remove('experience_match', 'Missing match_reason', claim?.requirement);
    return false;
  }
  if (!hasEvidence(claim)) {
    remove('experience_match', 'Evidence could not be traced to the CV, candidate text, or GitHub', claim?.requirement);
    return false;
  }
  matchedRequirements.add(normalizeText(claim.requirement));
  return true;
});
report.projects_to_highlight = report.projects_to_highlight.filter((claim) => {
  const ok = hasEvidence(claim);
  if (!ok) remove('projects_to_highlight', 'Evidence could not be traced to the CV, candidate text, or GitHub', claim?.project);
  return ok;
});

const gapTexts = new Set(report.skill_gaps.map((g) => normalizeText(g?.gap)));
for (const r of extracted.requirements) {
  const key = normalizeText(r.requirement);
  if (r.priority === 'Must-have' && !matchedRequirements.has(key) && !gapTexts.has(key)) {
    report.skill_gaps.push({ gap: r.requirement, priority: r.priority, how_to_prepare: 'No evidence was found for this requirement. Prepare a concrete example or a plan to learn it.' });
    data_notes.push(`A Must-have requirement had no match or gap, so it was added to skill_gaps: ${r.requirement}`);
  }
}

// Safe debug numbers only: no personal text from the CV
const original = JSON.parse(content);
return [{ json: { report, validation: { removed_claims, data_notes }, debug: {
  candidate_text_chars: evidence.candidate_text.length,
  repositories_found: evidence.github_repositories.length,
  ai_matches_before_check: (original.experience_match ?? []).length,
  ai_projects_before_check: (original.projects_to_highlight ?? []).length
} } }];
